randomizer.codigo:
(inp) => {
  // Randomizer: seed 0 = valores dos sliders; outro seed = design aleatorio repetivel
  const v = (o) => (o && o.value !== undefined ? o.value : o);
  const I = {};
  for (const k in inp) I[k] = v(inp[k]);
  const n = (val) => ({ type: Type.Number, meta: {}, value: val });
  // Intervalos seguros: [nome, min, max, passo]
  const R = [
    ['comprimento', 1400, 2200, 10],
    ['largura', 900, 1400, 10],
    ['altura', 450, 700, 10],
    ['larg_frente', 0.5, 1, 0.05],
    ['larg_meio', 0.5, 1, 0.05],
    ['larg_tras', 0.5, 1, 0.05],
    ['alt_frente', 0.5, 1, 0.05],
    ['alt_meio', 0.5, 1, 0.05],
    ['alt_tras', 0.5, 1, 0.05],
    ['n_longarinas', 3, 6, 1],
  ];
  // Gerador com seed (mulberry32), para o mesmo numero dar sempre o mesmo design
  const seed = Math.round(I.seed);
  let s = (seed * 2654435761) >>> 0;
  const rnd = () => {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const res = {};
  R.forEach(([k, a, b, p]) => {
    const r = rnd();
    const val = seed === 0 ? I[k] : Math.round((a + r * (b - a)) / p) * p;
    res['r_' + k] = n(val);
  });
  return res;
}
